package com.jarvis.homemultitool;

import android.Manifest;import android.app.Activity;import android.app.role.RoleManager;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;

/** Unified JARVIS HUD settings. */
public class SettingsActivity extends Activity{
 private static final int BG=Color.rgb(2,6,10),SUR=Color.rgb(5,16,27),CYAN=Color.rgb(91,224,255),WHITE=Color.rgb(242,247,255),MUTED=Color.rgb(126,157,184),GREEN=Color.rgb(71,232,177),RED=Color.rgb(255,102,116),BORDER=Color.rgb(24,91,139);private static final int REQ=51;private TextView roleState,wakeState,micState;
 private int dp(float x){return(int)(x*getResources().getDisplayMetrics().density+.5f);}private TextView tv(String s,float z){TextView v=new TextView(this);v.setText(s);v.setTextColor(WHITE);v.setTextSize(z);v.setGravity(Gravity.CENTER_VERTICAL);v.setIncludeFontPadding(true);return v;}private GradientDrawable box(int st,int fill,float r){GradientDrawable g=new GradientDrawable();g.setColor(fill);g.setCornerRadius(dp(r));if(st!=0)g.setStroke(dp(1),st);return g;}private LinearLayout.LayoutParams lp(int w,int h,int l,int t,int r,int b){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(w,h);p.setMargins(dp(l),dp(t),dp(r),dp(b));return p;}
 private TextView button(String s,View.OnClickListener c){TextView v=tv(s,13);v.setGravity(Gravity.CENTER);v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);v.setBackground(box(BORDER,0xE6071724,18));v.setPadding(dp(7),0,dp(7),0);v.setOnClickListener(c);if(Build.VERSION.SDK_INT>=26)v.setAutoSizeTextTypeUniformWithConfiguration(dp(9),dp(13),1,1);return v;}
 private void immersive(){try{if(Build.VERSION.SDK_INT>=30){getWindow().setDecorFitsSystemWindows(false);WindowInsetsController c=getWindow().getInsetsController();if(c!=null){c.hide(WindowInsets.Type.statusBars()|WindowInsets.Type.navigationBars());c.setSystemBarsBehavior(WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);}}else getWindow().getDecorView().setSystemUiVisibility(5894|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);}catch(Throwable ignored){}}
 @Override protected void onCreate(Bundle b){super.onCreate(b);immersive();getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);build();refresh();}
 private void build(){ScrollView sc=new ScrollView(this);sc.setBackgroundColor(BG);sc.setFillViewport(true);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(10),dp(18),dp(24));
  LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);TextView back=tv("‹",38);back.setGravity(Gravity.CENTER);back.setTextColor(CYAN);back.setBackground(box(BORDER,0xCC07131E,18));back.setOnClickListener(v->finish());head.addView(back,new LinearLayout.LayoutParams(dp(48),dp(48)));TextView title=tv("J A R V I S",23);title.setGravity(Gravity.CENTER);title.setTextColor(CYAN);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);title.setLetterSpacing(.16f);head.addView(title,new LinearLayout.LayoutParams(0,dp(48),1));TextView gear=tv("⚙",22);gear.setGravity(Gravity.CENTER);gear.setTextColor(CYAN);gear.setBackground(box(BORDER,0xCC07131E,18));head.addView(gear,new LinearLayout.LayoutParams(dp(48),dp(48)));root.addView(head);TextView sub=tv("СИСТЕМА • ГОЛОС • ВЫЗОВ • ПРИВАТНОСТЬ",10);sub.setTextColor(MUTED);sub.setTypeface(Typeface.DEFAULT,Typeface.BOLD);sub.setLetterSpacing(.08f);root.addView(sub,lp(-1,26,0,5,0,10));
  section(root,"СИСТЕМНЫЙ АССИСТЕНТ");LinearLayout card=card();row(card,"JARVIS как помощник Android","Позволяет вызывать JARVIS системной кнопкой ассистента",v->requestRole(),roleState=newState());root.addView(card,lp(-1,-2,0,0,0,10));
  section(root,"ВЫЗОВ «ДЖАРВИС»");LinearLayout wake=card();row(wake,"Фоновое ожидание фразы","Фоновый микрофон с постоянным уведомлением",v->toggleWake(),wakeState=newState());TextView note=tv("Включите этот режим, дайте доступ к микрофону и разрешите JARVIS работать без ограничений батареи. Android может показывать постоянное уведомление — это обязательный индикатор активного микрофона.",11);note.setTextColor(MUTED);note.setLineSpacing(0,1.15f);wake.addView(note,lp(-1,-2,0,8,0,4));TextView battery=button("РАЗРЕШИТЬ РАБОТУ БЕЗ ОГРАНИЧЕНИЙ БАТАРЕИ",v->openBatterySettings());wake.addView(battery,lp(-1,44,0,5,0,0));root.addView(wake,lp(-1,-2,0,0,0,10));
  section(root,"МИКРОФОН");LinearLayout mc=card();LinearLayout mr=new LinearLayout(this);mr.setGravity(Gravity.CENTER_VERTICAL);TextView mt=tv("Разрешение микрофона",14);mt.setTypeface(Typeface.DEFAULT,Typeface.BOLD);mr.addView(mt,new LinearLayout.LayoutParams(0,46,1));micState=newState();mr.addView(micState,lp(90,30,10,0,0,0));mc.addView(mr);mc.addView(button("РАЗРЕШИТЬ МИКРОФОН",v->requestMic()),lp(-1,44,0,8,0,0));root.addView(mc,lp(-1,-2,0,0,0,10));
  section(root,"РЕЧЬ");root.addView(button("НАСТРОЙКИ СИНТЕЗА РЕЧИ ANDROID",v->open("com.android.settings.TTS_SETTINGS")),lp(-1,46,0,0,0,7));root.addView(button("НАСТРОЙКИ ГОЛОСОВОГО ВВОДА ANDROID",v->open(Settings.ACTION_VOICE_INPUT_SETTINGS)),lp(-1,46,0,0,0,10));
  section(root,"РАЗРЕШЕНИЯ И ДИАГНОСТИКА");root.addView(button("РАЗРЕШЕНИЯ ПРИЛОЖЕНИЯ",v->openAppSettings()),lp(-1,46,0,0,0,7));root.addView(button("ТОЧНЫЕ БУДИЛЬНИКИ И НАПОМИНАНИЯ",v->open(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM)),lp(-1,46,0,0,0,7));TextView p=tv("Все действия JARVIS должны иметь реальный системный результат. Таймер использует системный AlarmManager как надёжный резерв, поэтому он сработает даже после закрытия приложения.",11);p.setTextColor(MUTED);p.setLineSpacing(0,1.15f);root.addView(p,lp(-1,-2,0,8,0,0));sc.addView(root);setContentView(sc);}
 private LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(15),dp(13),dp(15),dp(13));c.setBackground(box(BORDER,SUR,22));return c;}
 private void row(LinearLayout c,String title,String desc,View.OnClickListener click,TextView state){LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);LinearLayout text=new LinearLayout(this);text.setOrientation(LinearLayout.VERTICAL);TextView t=tv(title,14);t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);text.addView(t,new LinearLayout.LayoutParams(-1,dp(25)));TextView d=tv(desc,11);d.setTextColor(MUTED);d.setMaxLines(2);text.addView(d,new LinearLayout.LayoutParams(-1,dp(34)));r.addView(text,new LinearLayout.LayoutParams(0,dp(60),1));r.addView(state,lp(90,30,10,0,0,0));c.addView(r);c.addView(button("ОТКРЫТЬ / ИЗМЕНИТЬ",click),lp(-1,44,0,9,0,0));}
 private TextView newState(){TextView v=tv("—",10);v.setGravity(Gravity.CENTER);v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);v.setSingleLine(true);return v;}private void section(LinearLayout r,String s){TextView v=tv(s,10);v.setTextColor(CYAN);v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);v.setLetterSpacing(.11f);r.addView(v,lp(-1,25,2,5,0,3));}
 private void requestRole(){if(Build.VERSION.SDK_INT>=29){try{RoleManager rm=getSystemService(RoleManager.class);if(rm!=null&&rm.isRoleAvailable(RoleManager.ROLE_ASSISTANT)&&!rm.isRoleHeld(RoleManager.ROLE_ASSISTANT)){startActivityForResult(rm.createRequestRoleIntent(RoleManager.ROLE_ASSISTANT),41);return;}}catch(Throwable ignored){}}open(Settings.ACTION_VOICE_INPUT_SETTINGS);}
 private void requestMic(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},REQ);else refresh();}
 private void toggleWake(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},REQ);getSharedPreferences("jarvis",0).edit().putBoolean("wake_pending",true).apply();return;}boolean on=getSharedPreferences("jarvis",0).getBoolean("wake_enabled",false);getSharedPreferences("jarvis",0).edit().putBoolean("wake_enabled",!on).apply();Intent i=new Intent(this,JarvisWakeWordService.class);try{if(!on){if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}else stopService(i);}catch(Throwable e){getSharedPreferences("jarvis",0).edit().putBoolean("wake_enabled",false).apply();}refresh();}
 private void openBatterySettings(){try{Intent i=new Intent(Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS, Uri.parse("package:"+getPackageName()));startActivity(i);}catch(Throwable e){openAppSettings();}}
 private void refresh(){boolean role=JarvisVoiceInteractionService.isActive(this);roleState.setText(role?"АКТИВЕН":"НЕ ВЫБРАН");roleState.setTextColor(role?GREEN:MUTED);boolean wake=getSharedPreferences("jarvis",0).getBoolean("wake_enabled",false);wakeState.setText(wake?"ВКЛЮЧЕН":"ВЫКЛЮЧЕН");wakeState.setTextColor(wake?GREEN:MUTED);boolean mic=Build.VERSION.SDK_INT<23||checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED;micState.setText(mic?"РАЗРЕШЁН":"НЕТ");micState.setTextColor(mic?GREEN:RED);}
 private void open(String action){try{startActivity(new Intent(action));}catch(Throwable e){startActivity(new Intent(Settings.ACTION_SETTINGS));}}private void openAppSettings(){Intent i=new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS);i.setData(Uri.parse("package:"+getPackageName()));startActivity(i);}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==REQ&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED&&getSharedPreferences("jarvis",0).getBoolean("wake_pending",false)){getSharedPreferences("jarvis",0).edit().putBoolean("wake_pending",false).putBoolean("wake_enabled",true).apply();try{Intent i=new Intent(this,JarvisWakeWordService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}catch(Throwable ignored){}}refresh();}
 @Override protected void onResume(){super.onResume();immersive();if(roleState!=null)refresh();}
}
